#!/bin/sh
# xio Debian 12 / Ubuntu 24.04 laboratory recipe. Runs ONLY on the VPS after plan review in the UI.
# Client private key is generated by the app and is never an argument here.
set -eu
umask 077
test "$(id -u)" = 0 || { echo 'root required' >&2; exit 1; }
. /etc/os-release
case "$ID:$VERSION_ID" in
    ubuntu:24.04|debian:12) ;;
    *) echo 'Debian 12 or Ubuntu 24.04 required' >&2; exit 1 ;;
esac
test "$#" = 1 || exit 1
CLIENT_PUBLIC=$1
printf '%s' "$CLIENT_PUBLIC" | grep -Eq '^[A-Za-z0-9+/]{43}=$' || exit 1
test ! -e /etc/wireguard/xio0.conf || { echo 'existing xio0; refusing overwrite' >&2; exit 1; }
test ! -L /etc/wireguard/xio0.conf || exit 1
test ! -e /etc/sysctl.d/91-xio.conf || exit 1
ip link show xio0 >/dev/null 2>&1 && { echo 'interface already exists' >&2; exit 1; }
command -v python3 >/dev/null
ip -j -4 route show | python3 -c '
import ipaddress,json,sys
target=ipaddress.ip_network("10.77.0.0/24")
for r in json.load(sys.stdin):
    if r.get("dst","default")=="default": continue
    if ipaddress.ip_network(r["dst"],strict=False).overlaps(target): sys.exit("conflicting IPv4 route")
'
ip -j -6 route show | python3 -c '
import ipaddress,json,sys
target=ipaddress.ip_network("fd77:1::/64")
for r in json.load(sys.stdin):
    if r.get("dst","default")=="default": continue
    if ipaddress.ip_network(r["dst"],strict=False).overlaps(target): sys.exit("conflicting IPv6 route")
'
ss -H -lun | awk '{print $4}' | grep -Eq ':51820$' && { echo 'port in use' >&2; exit 1; }
if command -v ufw >/dev/null && ufw status | grep -q '^Status: active'; then
    echo 'Active UFW requires a separately reviewed firewall plan; installation stopped' >&2; exit 1
fi
OUT_IF=$(ip -4 route show default | awk 'NR==1 {print $5}')
printf '%s' "$OUT_IF" | grep -Eq '^[a-zA-Z0-9_.-]{1,15}$' || exit 1
OLD_FORWARD=$(sysctl -n net.ipv4.ip_forward)
SUCCESS=0
CREATED=0
cleanup() {
    if test "$SUCCESS" != 1 && test "$CREATED" = 1; then
        systemctl stop wg-quick@xio0 >/dev/null 2>&1 || true
        systemctl disable wg-quick@xio0 >/dev/null 2>&1 || true
        rm -f /etc/sysctl.d/91-xio.conf
        sysctl -q -w "net.ipv4.ip_forward=$OLD_FORWARD" || true
        # Retain private config for manual recovery, never print it.
    fi
}
trap cleanup EXIT
# Packages are installed from the host's configured distribution repository.
# Resolved package versions are recorded in the server-side installation log.
LOG=/var/log/xio-install.log
test ! -L "$LOG" || exit 1
: > "$LOG"
chmod 600 "$LOG"
export DEBIAN_FRONTEND=noninteractive
apt-get update >>"$LOG" 2>&1
apt-get install -y --no-install-recommends wireguard-tools iptables >>"$LOG" 2>&1
dpkg-query -W wireguard-tools iptables >>"$LOG"
if test ! -d /etc/wireguard; then mkdir -m 700 /etc/wireguard; fi
SERVER_PRIVATE=$(wg genkey)
SERVER_PUBLIC=$(printf '%s' "$SERVER_PRIVATE" | wg pubkey)
CREATED=1
cat > /etc/wireguard/xio0.conf <<EOF
[Interface]
PrivateKey = $SERVER_PRIVATE
Address = 10.77.0.1/24, fd77:1::1/64
ListenPort = 51820
MTU = 1280
PostUp = iptables -I FORWARD -i %i -m comment --comment xio-v1 -j ACCEPT; iptables -I FORWARD -o %i -m conntrack --ctstate RELATED,ESTABLISHED -m comment --comment xio-v1 -j ACCEPT; iptables -t nat -A POSTROUTING -s 10.77.0.0/24 -o $OUT_IF -m comment --comment xio-v1 -j MASQUERADE; ip6tables -I FORWARD -i %i -m comment --comment xio-v1 -j DROP
PostDown = iptables -D FORWARD -i %i -m comment --comment xio-v1 -j ACCEPT; iptables -D FORWARD -o %i -m conntrack --ctstate RELATED,ESTABLISHED -m comment --comment xio-v1 -j ACCEPT; iptables -t nat -D POSTROUTING -s 10.77.0.0/24 -o $OUT_IF -m comment --comment xio-v1 -j MASQUERADE; ip6tables -D FORWARD -i %i -m comment --comment xio-v1 -j DROP

[Peer]
PublicKey = $CLIENT_PUBLIC
AllowedIPs = 10.77.0.2/32, fd77:1::2/128
EOF
unset SERVER_PRIVATE
chmod 600 /etc/wireguard/xio0.conf
printf 'net.ipv4.ip_forward=1\n' > /etc/sysctl.d/91-xio.conf
sysctl -q -w net.ipv4.ip_forward=1
systemctl enable --now wg-quick@xio0 >>"$LOG" 2>&1
systemctl is-active --quiet wg-quick@xio0
test "$(wg show xio0 public-key)" = "$SERVER_PUBLIC"
SUCCESS=1
printf 'XIO_SERVER_KEY=%s\n' "$SERVER_PUBLIC"
